\label{lem:backward-hole}
For every admissible family,
\begin{align}
 &\sum_{J\in\mathcal J}
 \left(
 \frac{P^\alpha(J,\mathbf 1_{I\setminus\gamma J}\omega)}
 {\ell(J)}\right)^2
 \|P_J^\sigma\mathbf x\|_2^2
\leq C\beta
 \bigl(\mathfrak T_{\mathbf R_\Psi^{\alpha,n}}^{\mathrm{dual}}\bigr)^2
 \omega(I).
 \label{eq:backward-hole}
\end{align}

\label{lem:axis-sections}
Assume \(n\geq2\) and \eqref{eq:coordinate-monotonicity}.
\begin{enumerate}
\item For every \(Q\in\Omega\mathcal Q^n\), \(Q\cap L_0\) is empty or a
half-open interval.
\item If \(S=[a,b)e_1\subset L_0\), there is
\(Q_S\in\Omega\mathcal Q^n\) such that \(Q_S\cap L_0=S\), and
\begin{equation}\label{eq:auxiliary-size}
 \ell(Q_S)\leq C_\Omega(b-a),\qquad
Q_S\cup3Q_S\subset
 \{x:\operatorname{dist}(x,S)\leq C_\Omega(b-a)\}.
\end{equation}
\end{enumerate}

The forward estimate follows from
\(\widetilde\omega_i\leq\widetilde\omega^{(i)}\).
By \cref{lem:axis-sections}, \(Q\cap L_0\) is a half-open interval.  Put \(S_Q=Q\cap I_i\). If \(\widetilde\omega_i(Q)=0\), the dual estimate is trivial.  Otherwise
\(S_Q\) is a nonempty half-open interval of positive length.  Let
\(P_Q=Q_{S_Q}\) be given by \cref{lem:axis-sections}.  By
\eqref{eq:auxiliary-size},
\begin{align*}
 3P_Q
 &\subset\{x:\operatorname{dist}(x,S_Q)\leq C_{\Omega}|S_Q|\}
 \subset\{x:\operatorname{dist}(x,I_i)\leq C_{\Omega}|I_i|\}.
\end{align*}
Since \(C_\Omega\leq C_{\rm ax}\), our choice of \(A\) gives
\(A>2C_\Omega\).  Hence
\eqref{eq:tube-localization} gives
\begin{equation}\label{eq:tripled-support-on-axis}
 3P_Q\cap\operatorname{supp}\widetilde\omega^{(i)}
 \subset3P_Q\cap\widetilde{\Gamma}^{(i)}
 \subset\Psi_i^{-1}(\widehat{\Gamma}_i)\subset L_0.
\end{equation}

The half-open construction of \(\Gamma_i\) gives
\begin{equation}\label{eq:restriction-on-axis-interval}
 \mathbf 1_{I_i}\widetilde\omega^{(i)}=\widetilde\omega_i.
\end{equation}
For the last arc of an open curve, \eqref{eq:ghost-zero} shows that
\(\widetilde\omega^{(i)}\) has zero mass on the added segment.  Since
\(P_Q\cap L_0=S_Q\), equations
\eqref{eq:tripled-support-on-axis} and
\eqref{eq:restriction-on-axis-interval} give
\begin{align}
 \mathbf 1_{P_Q}\widetilde\omega^{(i)}
 &=\mathbf 1_{P_Q\cap L_0}\widetilde\omega^{(i)}
 =\mathbf 1_{S_Q}\widetilde\omega^{(i)}
 =\mathbf 1_{S_Q}\widetilde\omega_i
 =\mathbf 1_Q\widetilde\omega_i.
 \label{eq:exact-measure-localization}
\end{align}
Every partition point belongs to one half-open arc, so the identity also
holds at atoms on the partition boundaries.
Split the dual testing integral over \(Q\setminus3P_Q\) and
\(Q\cap3P_Q\).  Put \(a_{P_Q}=|P_Q|^{1/n}\).  If
\(x\notin3P_Q\) and \(y\in P_Q\), then \(|x-y|\approx_\Omega a_{P_Q}+|x-c_{P_Q}|\). Consequently,
\begin{align*}
 &\int_{Q\setminus3P_Q}
 |\mathbf R_{\Psi_i}^{\alpha,n}
   (\mathbf 1_{P_Q}\widetilde\omega^{(i)})(x)|^2
d\widetilde\sigma_i(x)\\
 &\quad\leq C\widetilde\omega^{(i)}(P_Q)^2
 \int_{P_Q^c}
 \frac{d\widetilde\sigma_i(x)}
 {(a_{P_Q}+|x-c_{P_Q}|)^{2(n-\alpha)}}\\
 &\quad=C\widetilde\omega^{(i)}(P_Q)
 \frac{\widetilde\omega^{(i)}(P_Q)}{a_{P_Q}^{n-\alpha}}
 \mathcal P^\alpha
   (P_Q,\mathbf 1_{P_Q^c}\widetilde\sigma_i)\leq C\mathcal A_{2,\Omega}^\alpha
 \widetilde\omega^{(i)}(P_Q).
\end{align*}
\Cref{lem:local-tripled} controls the second part.  Finally,
\eqref{eq:exact-measure-localization} gives \(\widetilde\omega^{(i)}(P_Q)=\widetilde\omega_i(Q)\). This proves \eqref{eq:localized-dual-testing}.  Since
\(|S_Q|\leq|I_i|\), we have
\(\ell(P_Q)\lesssim_\Omega|I_i|\), independently of \(\ell(Q)\).
Thus the estimate holds for testing cubes of every size.

\label{lem:A2-restriction}
For every fixed globally biLipschitz quasicube map \(\Omega\) and every
Borel set \(E\),
\begin{equation}\label{eq:A2-restriction}
 \mathfrak A_{2,\Omega}^\alpha(\sigma,\mathbf 1_E\omega)
 \leq C_\Omega\mathfrak A_{2,\Omega}^\alpha(\sigma,\omega).
\end{equation}

\label{thm:Green-gradient}
Under the assumptions above, the uniformly truncated estimate
\[
 \sup_{0<\varepsilon<R}
 \|\mathbf G_{\Omega,\varepsilon,R,\sigma}f\|_{L^2(\omega)}
 \leq C\|f\|_{L^2(\sigma)}
\]
holds if and only if the following conditions hold:
\begin{enumerate}
\item the two one-tailed \(\mathcal A_2^1\) conditions with holes;
\item the two punctured \(A_2^1\) conditions;
\item the forward and dual Green testing conditions over all rotated
cubes.
\end{enumerate}
If \(M_\Omega(\sigma,\omega) :=\bigl(\sigma(\Gamma)\omega(\overline\Omega)\bigr)^{1/2}\), then
\[
 \mathfrak N_{\mathbf G_\Omega}+M_\Omega
 \approx
 \sqrt{\mathfrak A_2^1}
 +\mathfrak T_{\mathbf G_\Omega}
 +\mathfrak T_{\mathbf G_\Omega}^{\mathrm{dual}}
 +M_\Omega.
\]
The comparison constants may also depend on \(\Omega\), on
\(\operatorname{dist}(\Gamma,\partial\Omega)\), and on the curve constants in
\cref{thm:main}.
